import { HStack } from '@chakra-ui/react'
import SingleCoinImage, { SingleCoinImageProps } from './SingleCoinImage'

interface CoinPairImageProps extends SingleCoinImageProps {
  coinAIconUrl?: string
  coinBIconUrl?: string
  coinACoinType?: string
  coinBCoinType?: string
  showATag?: boolean
  showBTag?: boolean
  variant?: 'border' | ''
}
export default function CoinPairImage(props: CoinPairImageProps) {
  const { coinAIconUrl, coinBIconUrl, coinACoinType, coinBCoinType, ml, showATag, showBTag, ...rest } = props
  return (
    <HStack gap="0px">
      <SingleCoinImage imageUrl={coinAIconUrl} {...rest} showTag={showATag} coinType={coinACoinType} />
      <SingleCoinImage imageUrl={coinBIconUrl} {...rest} ml={ml ? ml : '0px'} showTag={showBTag} coinType={coinBCoinType} />
    </HStack>
  )
}
