import { LabelItem, Token } from '@cetus/types'
import { toLongCoinType } from '@cetus/utils'
import { create, StateCreator } from 'zustand'
import { persist } from 'zustand/middleware'
interface TokenSelectStore {
  collectList: Array<Token>
  setCollectList: (list: Array<Token>) => void
  collectObj: {
    [key: string]: Token
  }
  filterTokenLoading: boolean
  setFilterTokenLoading: (value: boolean) => void
  filterTokenList: Array<Token>
  setFilterTokenList: (list: Array<Token>) => void
  importTokenList: Array<Token>
  setImportTokenList: (list: Array<Token>) => void
  liquidityTrustTokenList: Array<Token>
  setLiquidityTrustTokenList: (list: Array<Token>) => void
  isShowImportBtn: boolean
  setShowImportBtn: (value: boolean) => void
  trustedListLabel: Array<LabelItem>
  setTrustedListLabel: (list: Array<LabelItem>) => void

  tokenModalOpacity: number
  setTokenModalOpacity: (data: number) => void
  userCollectObj: {
    [key: string]: Token
  }
  userCollectList: Array<Token>
  setUserCollectList: (list: Array<Token>) => void
}
const store: StateCreator<TokenSelectStore> = (set, get) => ({
  collectList: [],
  collectObj: {},
  setCollectList: (list: Array<Token>) => {
    set(() => ({
      collectList: list,
      collectObj: Object.fromEntries(list.map(item => [item.coin_type, item]))
    }))
  },
  filterTokenLoading: false,
  setFilterTokenLoading: (value: boolean) => {
    set(() => ({
      filterTokenLoading: value
    }))
  },
  filterTokenList: [],
  setFilterTokenList: (list: Array<Token>) => {
    set(() => ({
      filterTokenList: list
    }))
  },
  importTokenList: [],
  setImportTokenList: (list: Array<Token>) => {
    set(() => ({
      importTokenList: list
    }))
  },
  liquidityTrustTokenList: [],
  setLiquidityTrustTokenList: (list: Array<Token>) => {
    set(() => ({
      liquidityTrustTokenList: list
    }))
  },
  isShowImportBtn: false,
  setShowImportBtn: (value: boolean) => {
    set(() => ({
      isShowImportBtn: value
    }))
  },
  trustedListLabel: [],
  setTrustedListLabel: (list: Array<LabelItem>) => {
    set(() => ({
      trustedListLabel: list
    }))
  },

  tokenModalOpacity: 1,
  setTokenModalOpacity: (data: number) => {
    set(() => ({
      tokenModalOpacity: data
    }))
  },
  userCollectList: [],
  userCollectObj: {},
  setUserCollectList: (list: Array<Token>) => {
    set(() => ({
      userCollectList: list,
      userCollectObj: Object.fromEntries(list.map(item => [toLongCoinType(item.coin_type), item]))
    }))
  }
})

const useTokenSelectStore = create(
  persist(store, {
    name: 'useTokenSelectStore',
    partialize: state => {
      const { importTokenList, liquidityTrustTokenList } = state
      return { importTokenList, liquidityTrustTokenList }
    }
  })
)
export default useTokenSelectStore
