import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import { Input, InputGroup, InputRightElement } from '@chakra-ui/react'
import { useEffect, useRef } from 'react'

type SearchInputProps = {
  inputValue: string | number | readonly string[] | undefined
  changeInputValue: (value: string) => void
  isFrom?: string
  inputFontSize?: string
  isWidget?: boolean
  placeholder?: string
}
export function SearchInput({
  inputValue,
  changeInputValue,
  isFrom = '',
  inputFontSize = 'sm',
  isWidget = false,
  placeholder = 'Search by token or address'
}: SearchInputProps) {
  const inputRef = useRef(null)
  const { isApp } = useWindowWidth()
  useEffect(() => {
    if (!isApp) {
      // 页面加载后自动聚焦
      inputRef.current.focus()
    }
  }, [isApp])
  return (
    // <InputBox p="0" borderRadius="8px" bg={isWidget ? 'swap_bg_secondary' : 'bg_secondary'} focusBorder="text_highlight">
    <InputGroup>
      <Input
        _hover={{
          bg: isWidget ? 'swap_bg_secondary' : 'bg_secondary'
        }}
        bg={isWidget ? 'swap_bg_secondary' : 'bg_secondary'}
        ref={inputRef}
        borderRadius="8px"
        h="36px"
        border="none"
        variant="outline"
        value={inputValue}
        onChange={e => {
          changeInputValue(e.target.value)
        }}
        fontWeight="500"
        textAlign="left"
        fontSize={inputFontSize}
        placeholder={placeholder}
        pr={
          isFrom == 'pools'
            ? '22px'
            : {
                base: '28px',
                md: '28px',
                lg: '28px'
              }
        }
        pl={
          isFrom == 'pools'
            ? '8px'
            : {
                md: '12px',
                lg: '16px'
              }
        }
      />
      <InputRightElement>
        {inputValue ? (
          <Icon
            xlinkHref="#icon-icon_close"
            position="absolute"
            top="8px"
            right={isFrom == 'pools' ? '4px' : '8px'}
            onClick={e => {
              e.stopPropagation()
              changeInputValue('')
            }}
          />
        ) : null}
      </InputRightElement>
    </InputGroup>
    // </InputBox>
  )
}
