export const getFastestRpc = (rpcs: string[]): Promise<string> => {
  return new Promise((resolve, reject) => {
    if (!rpcs || rpcs.length === 0) {
      return reject(new Error('Rpc list cannot be empty.'))
    }

    // const worker = new Worker(new URL('/worker/rpc.worker.js', import.meta.url))
    const worker = new Worker('/worker/rpc.worker.js')
    worker.postMessage(rpcs)

    worker.onmessage = (event: MessageEvent) => {
      resolve(event.data) // 返回最快域名
      worker.terminate()
    }

    worker.onerror = error => {
      reject(error)
    }
  })
}
